const environment=computed({get:()=>tab.value==='query'?activeSession.value.environment:operationEnvironment.value,set:async value=>{const old=tab.value==='query'?activeSession.value.environment:operationEnvironment.value;if(old&&old!==value&&environments.value.find(e=>e.name===value)?.protected&&!await confirmAction('即将切换到受保护环境。请核对目标，切换不会执行任何操作。'))return;if(tab.value==='query')activeSession.value.environment=value;else operationEnvironment.value=value}})
function newQuery(body,internal=false){if(busy.value&&!internal)return;if(sessions.value.length>=10){error.value='最多同时打开 10 个查询页签，请先关闭不需要的页签';return}const prev=activeSession.value;sessions.value.push({id:++sessionID,name:'查询 '+sessionID,environment:body?.environment||prev.environment,targetMode:body?.connection?'connection':body?'application':prev.targetMode,query:body?{connection:body.connection||'',database:body.database||'',service:body.service,resource_alias:body.resource_alias,sql:body.sql||'',commands:body.commands||''}:{...prev.query,sql:'',commands:''},result:null,previous:null,executedText:'',fields:[...prev.fields],browser:kind==='dbms'&&(!body||queryContext(body)===queryContext({...prev.query,environment:prev.environment}))?{tables:[...(prev.browser.tables||[])],tablesLoaded:!!prev.browser.tablesLoaded,schemas:{...prev.browser.schemas},table:prev.browser.table||''}:{},advanced:true,navigationOpen:prev.navigationOpen});sessionIndex.value=sessions.value.length-1;tab.value='query';resourcesFor(query.value.service,true)}
