async function closeQuery(id){
 if(busy.value)return
 const session=sessions.value.find(s=>s.id===id);if(!session)return
 if((session.query.sql||session.query.commands)&&!await confirmAction('关闭「'+session.name+'」？内容仅保留在当前页面，关闭后不能恢复。','关闭查询页签',{confirmButtonText:'关闭页签',cancelButtonText:'继续编辑'}))return
 if(busy.value||!sessions.value.some(s=>s.id===id))return
 if(sessions.value.length===1)newQuery(undefined,true)
 const next=closeQuerySession(sessions.value,id,activeSession.value.id);if(!next)return
 sessions.value=next.sessions;sessionIndex.value=next.index;resourcesFor(query.value.service,true);loadPolicy()
}
async function loadTarget(){const seq=++targetRequest.value;target.value=null;if(!activeSession.value.environment||!(query.value.connection||(query.value.service&&query.value.resource_alias))||kind==='dbms'&&query.value.connection&&!selectedDatabase.value)return;try{const data=await api('api/query-target?'+new URLSearchParams({connection:query.value.connection||'',database:query.value.database||'',service:query.value.service||'',resource_alias:query.value.resource_alias||'',environment:activeSession.value.environment}));if(seq===targetRequest.value)target.value=data}catch(e){if(seq===targetRequest.value)error.value=e.message}}
function rememberQuery(body,result){recentQueries.value.unshift({body:{...body},at:Date.now(),rows:result?.rows?.length||0,elapsed:result?.elapsed_ms});recentQueries.value=recentQueries.value.slice(0,30);if(result?.metadata==='schema')activeSession.value.fields=(result.rows||[]).map(r=>r.field)}
