const filteredTickets=computed(()=>tickets.value.filter(v=>(!historyText.value||JSON.stringify([v.id,v.owner,v.query.service,v.query.connection,v.query.environment]).includes(historyText.value))&&(historyFilter.value!=='mine'||v.owner===me.value.username)&&(historyFilter.value!=='review'||(v.status==='pending_approval'&&v.owner!==me.value.username&&Object.values(v.approvers||{}).every(a=>a.split(',').map(s=>s.trim()).includes(me.value.username))))))
async function keyChange(command){if(!keyName.value){error.value='请填写准确 Key';return}if(!await queryToChange(activeSession.value.browser.lastQuery))return;if(form.value&&tab.value==='operations'){form.value.title='缓存操作 · '+keyName.value;form.value.redis.commands=command+' '+JSON.stringify(keyName.value)+(command==='EXPIRE'?' 600':'');form.value.rollback_plan='请确认业务可重建缓存；此操作不自动回滚。'}}
function inspectKey(key){keyName.value=key;query.value.commands='TYPE '+JSON.stringify(key)+'\nTTL '+JSON.stringify(key)}
