const stateLabel={draft:'草稿',ready:'就绪',pending:'待执行',executing:'执行中',success:'成功',pending_approval:'待审核',approved:'待执行',running:'执行中',completed:'完成',failed:'失败',rejected:'已拒绝',canceled:'已取消'}
