function hashNavigation(){const hash=location.hash.slice(1).replace(/^\//,''),[id,params]=hash.split('?');const wid=Number(new URLSearchParams(params).get('work_item'));if(wid>0)syncWorkItem.value={id:wid};if(id==='settings'||nav.value.some(n=>n.id===id)){tab.value=id;if(id==='operations'&&!form.value&&!operationList.value)open()}}
