const canReview=computed(()=>run.value&&me.value.username!==run.value.owner&&(run.value.plan.environment.approvers||'').split(',').map(s=>s.trim()).includes(me.value.username))
const canManage=computed(()=>run.value&&(me.value.role==='admin'||me.value.username===run.value.owner))
const canQueryReview=computed(()=>queryTicket.value?.status==='pending_approval'&&queryTicket.value.owner!==me.value.username&&Object.values(queryTicket.value.approvers||{}).every(a=>a.split(',').map(v=>v.trim()).includes(me.value.username)))
const queryOwner=computed(()=>queryTicket.value?.owner===me.value.username)
const statusText=v=>stateLabel[v]||v
async function api(path,opt){const url=path.startsWith('api/')?`api/workbench/${kind}/${path.slice(4)}`:path;const r=await fetch(url,opt),v=await r.json().catch(()=>({}));if(!r.ok)throw new Error(v.error||`请求失败（${r.status}）`);return v}
provide('api',api);provide('resourcePlugin',kind)
const post=(path,body)=>api(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)})
const list=v=>Array.isArray(v)?v:[]
async function action(fn){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
let activeContext='',policyRequest=0
async function loadPolicy(){const seq=++policyRequest;policy.value=null;policyError.value='';if(!environment.value)return;try{const p=await api(`api/policy?environment=${encodeURIComponent(environment.value)}`);if(seq===policyRequest){policy.value=p;policyDraft.value={...p}}}catch(e){if(seq===policyRequest)policyError.value=e.message}}
async function load(){loading.value=true;try{
 const [apps,envs,ops,history,requests,catalog,identity,dbConnections]=await Promise.all([api('api/services'),api('api/environments'),api('api/changes'),api('api/delivery/runs'),api('api/query-requests'),fetch('/api/registry/applications').then(r=>r.ok?r.json():[]).catch(()=>[]),fetch('/api/me').then(r=>r.ok?r.json():{}).catch(()=>({})),api('api/connections')])
 connections.value=list(dbConnections);services.value=[...new Map([...list(apps),...list(catalog)].map(a=>[a.name,{name:a.name,display_name:a.display_name,identifier:a.identifier}])).values()];environments.value=list(envs);changes.value=list(ops);runs.value=list(history);tickets.value=list(requests);me.value=identity
 if(!environments.value.some(e=>e.name===environment.value))environment.value=environments.value.find(e=>e.name===activeContext)?.name||environments.value[0]?.name||''
 if(run.value)run.value=runs.value.find(v=>v.id===run.value.id)||run.value
 if(queryTicket.value)queryTicket.value=tickets.value.find(v=>v.id===queryTicket.value.id)||queryTicket.value
 await loadPolicy()
}catch(e){error.value=e.message}finally{loading.value=false}}
let resourceRequests={query:0,change:0}
async function resourcesFor(service,querying=false){const key=querying?'query':'change',seq=++resourceRequests[key],target=querying?queryAliases:aliases;target.value=[];if(!service)return;try{const data=await api(`api/services/${encodeURIComponent(service)}/resources`);if(seq===resourceRequests[key])target.value=list(data.requirements).filter(r=>r.kind===changeKind).map(r=>({value:r.alias,label:r.alias}))}catch(e){if(seq===resourceRequests[key])error.value=e.message}}
function invalidate(){plan.value=null;templateID.value=0}
watch([environment,reason],invalidate);watch(environment,loadPolicy)
watch(()=>JSON.stringify(form.value),()=>{if(dirty.value)invalidate()})
function navigate(id){if(busy.value)return;settingsOpen.value=false;if(id!=='query'&&!operationEnvironment.value)operationEnvironment.value=activeSession.value.environment;if(id==='operations'&&!form.value&&!operationList.value){open();return}tab.value=id;error.value='';if(id==='history')load()}
async function open(c){if(busy.value)return;if(dirty.value&&!await confirmAction('放弃未保存的变更？'))return;operationList.value=false;form.value=c?JSON.parse(JSON.stringify(c)):{kind:changeKind,title:'',service:'',risk_level:'medium',rollback_plan:'',sql:kind==='dbms'?{resource_alias:'',content:'',max_affected_rows:100}:undefined,redis:kind==='redis'?{resource_alias:'',commands:''}:undefined};original.value=JSON.stringify(form.value);invalidate();tab.value='operations';error.value='';resourcesFor(form.value.service);return true}
async function save(markReady=false){if(!form.value?.title.trim()||!form.value.service)throw new Error('请填写标题、应用和变更内容');const f=form.value;form.value=await api('api/changes'+(f.id?'/'+f.id:''),{method:f.id?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(f)});original.value=JSON.stringify(form.value);if(markReady&&form.value.status!=='ready'){form.value=await post(`api/changes/${form.value.id}/ready`,{});original.value=JSON.stringify(form.value)}invalidate();await load()}
async function preview(){invalidate();if(!form.value||!environment.value)throw new Error('请选择变更和目标环境');if(dirty.value||!form.value.id)await save();const nodes=[{id:'operation',kind:changeKind,name:title,change_ids:[form.value.id]}];const tpl=await post('api/delivery/templates',{name:`${title}变更`,workbench:kind,mode:'fixed',services:[],nodes});templateID.value=tpl.id;plan.value=await post('api/delivery/preview',{template_id:tpl.id,environment:environment.value,reason:reason.value,nodes})}
async function submit(){if(!plan.value||!templateID.value||plan.value.blockers?.length)throw new Error('请先完成预检并解决阻断项');const snapshot=plan.value,id=templateID.value;if(dirty.value)throw new Error('内容已变化，请重新预检');if(form.value.status!=='ready'){form.value=await post(`api/changes/${form.value.id}/ready`,{});original.value=JSON.stringify(form.value)}run.value=await post('api/delivery/runs',{template_id:id,environment:environment.value,reason:reason.value,nodes:snapshot.nodes});if(verification())runVerification.value[run.value.id]=JSON.parse(JSON.stringify(verification()));invalidate();tab.value='history';recordType.value='changes';await load()}
async function runAction(name){if(name==='advance'&&!await confirmAction('执行此快照中的变更？请核对目标环境。'))return;run.value=await post(`api/delivery/runs/${run.value.id}/${name}`,{digest:run.value.digest});await load()}
async function bind(){bindingService.value=tab.value==='query'?query.value.service:form.value?.service;if(!bindingService.value)throw new Error('请先选择应用');await post('api/applications',{name:bindingService.value});showBindings.value=true}
function changeQueryTargetMode(){query.value.connection='';query.value.service='';query.value.resource_alias='';query.value.database='';queryAliases.value=[]}
async function readQuery(selected){if(!policy.value)throw new Error('审批设置尚未加载，不能执行查询');if(!environment.value||(activeSession.value.targetMode==='connection'?!query.value.connection:(!query.value.service||!query.value.resource_alias)))throw new Error(activeSession.value.targetMode==='connection'?(kind==='dbms'?'请选择数据库连接和环境':'请选择 Redis 连接和环境'):'请选择应用、资源和环境');if(kind==='dbms'&&query.value.connection&&!selectedDatabase.value)throw new Error('请选择数据库（schema）');if(!(kind==='dbms'?query.value.sql:query.value.commands).trim())throw new Error('请先填写查询内容');const body={...query.value,environment:environment.value};if(typeof selected==='string'&&selected.trim())body[kind==='dbms'?'sql':'commands']=selected;if(policy.value.query_approval){queryTicket.value=await post('api/query-requests',body);recordType.value='queries';tab.value='history';await load()}else {browserController=new AbortController();const timer=setTimeout(()=>browserController?.abort(),kind==='redis'?7000:35000);try{queryResult.value=await api('api/query',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal:browserController.signal});activeSession.value.executedText=body[kind==='dbms'?'sql':'commands'];rememberQuery(body,queryResult.value)}catch(e){if(e.name==='AbortError')throw new Error('查询已取消或超时');throw e}finally{clearTimeout(timer);browserController=null}}}
let browserController=null
const browserTickets=new Map()
function browserTicketSession(ticket){const origin=browserTickets.get(ticket.id);return origin?sessions.value.findIndex(s=>s.id===origin.sessionID&&queryContext({...s.query,environment:s.environment})===origin.context):-1}
async function browserQuery(patch){
 if(busy.value||tab.value!=='query')return null
 if(!policy.value||!target.value)throw new Error('请选择连接并等待审批设置加载')
 const session=activeSession.value,body={...query.value,...patch,environment:session.environment}
 busy.value=true
 browserController=new AbortController()
 const timer=setTimeout(()=>browserController?.abort(),kind==='redis'?7000:35000)
 try{
  if(policy.value.query_approval){queryTicket.value=await post('api/query-requests',body);browserTickets.set(queryTicket.value.id,{sessionID:session.id,context:queryContext(body)});recordType.value='queries';tab.value='history';await load();return null}
  const result=await api('api/query',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal:browserController.signal})
  if(activeSession.value.id!==session.id||queryContext({...session.query,environment:session.environment})!==queryContext(body))return null
  session.browser.lastQuery={...body};rememberQuery(body,result)
  return result
 }catch(e){if(e.name==='AbortError')throw new Error('查询已取消或超时，请缩小范围后重试');throw e}
 finally{clearTimeout(timer);browserController=null;busy.value=false}
}
async function ticketAction(name){
 const origin=browserTicketSession(queryTicket.value)
 if(name==='execute'&&!queryTicket.value.query.task_id&&origin<0&&sessions.value.length>=10)throw new Error('请先关闭一个查询页签，再执行已批准查询')
 const data=await post(`api/query-requests/${queryTicket.value.id}/${name}`,{})
 if(name==='execute'){
  queryTicket.value=data.ticket
  if(data.ticket.query.task_id){syncResult.value={ticket:data.ticket,result:data.result};tab.value='sync'}
  else if(origin>=0){sessionIndex.value=origin;tab.value='query';activeSession.value.advanced=false;activeSession.value.browser.lastQuery={...data.ticket.query};activeSession.value.browser.restore={...data.ticket.query,result:data.result};rememberQuery(data.ticket.query,data.result)}
  else{newQuery(data.ticket.query,true);await nextTick();queryResult.value=data.result;activeSession.value.executedText=data.ticket.query[kind==='dbms'?'sql':'commands'];rememberQuery(data.ticket.query,data.result)}
 }else queryTicket.value=data
 await load()
}
async function approveComparison(q){await action(async()=>{queryTicket.value=await post('api/query-requests',q);recordType.value='queries';tab.value='history';await load()})}
async function savePolicy(){if(me.value.role!=='admin')throw new Error('仅管理员可修改审批设置');if(!await confirmAction('保存当前环境的查询与变更审批设置？不会执行查询或变更。'))return;policy.value=await api(`api/policy?environment=${encodeURIComponent(environment.value)}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(policyDraft.value)});policyDraft.value={...policy.value};invalidate()}
watch([()=>activeSession.value.id,()=>activeSession.value.environment,()=>query.value.service,()=>query.value.resource_alias,()=>query.value.connection,()=>query.value.database],()=>{loadTarget();loadPolicy()});watch(()=>[activeSession.value.id,query.value.service,query.value.resource_alias,query.value.connection,activeSession.value.environment,query.value.database],(now,old)=>{if(now[0]===old[0]){queryResult.value=null;activeSession.value.previous=null;activeSession.value.executedText='';activeSession.value.fields=[];activeSession.value.browser={};browserController?.abort()}})
function closeEditor(){operationList.value=true;invalidate()}
function syncGenerated(){load();if(embedded&&syncWorkItem.value)window.parent.postMessage({type:'work-item.changed',id:syncWorkItem.value.id},location.origin)}
async function queryToChange(body){if(busy.value)return;const source=body?.environment?{...body}:{...query.value,environment:activeSession.value.environment};if(!await open())return;operationEnvironment.value=source.environment;form.value.service=source.service;form.value.reference=JSON.stringify({workbench_query:source});form.value.title=(kind==='dbms'?'SQL 变更':'缓存变更')+' · '+source.service;if(kind==='dbms')form.value.sql.resource_alias=source.resource_alias;else form.value.redis.resource_alias=source.resource_alias;resourcesFor(source.service);return true}
watch(()=>[target.value,tab.value,query.value.connection,query.value.service,query.value.resource_alias],()=>{if(embedded){const t=target.value;const label=tab.value!=='query'?({history:'执行记录',operations:'变更操作',settings:'审批设置',sync:'数据同步'})[tab.value]||'工作台':t?[t.connection,kind==='dbms'?t.database:'DB '+t.db].filter(Boolean).join(' / '):query.value.connection||(query.value.service&&query.value.resource_alias?query.value.service+' / '+query.value.resource_alias:'未选择连接');window.parent.postMessage({type:'workspace.label',label},location.origin)}},{immediate:true})
function contextMessage(e){if(e.source===window.parent&&e.origin===location.origin&&e.data?.type==='context.sync'){activeContext=e.data.environment;if(!environment.value&&environments.value.some(v=>v.name===activeContext))environment.value=activeContext}}
let narrowWorkspace=window.innerWidth<=760
function adaptWorkspace(){const narrow=window.innerWidth<=760;if(narrow!==narrowWorkspace){narrowWorkspace=narrow;for(const session of sessions.value)session.navigationOpen=!narrow}}
watch(()=>[dirty.value,busy.value,syncActivity.value.dirty,syncActivity.value.busy,sessions.value.some(s=>s.query.sql||s.query.commands)],([changeDirty,busy,syncDirty,syncBusy,queryDirty])=>{if(embedded)window.parent.postMessage({type:'workspace.dirty',dirty:!!(changeDirty||syncDirty||queryDirty),busy:busy||syncBusy},location.origin)})
function beforeWorkspaceNavigation(e){if(busy.value||syncActivity.value.busy)e.preventDefault();else if(syncActivity.value.dirty){e.preventDefault();notify('请先保存或取消数据任务配置','warning')}}
function beforeUnload(e){if(dirty.value||syncActivity.value.dirty||sessions.value.some(s=>s.query.sql||s.query.commands)){e.preventDefault();e.returnValue=''}}
onMounted(()=>{window.addEventListener('resize',adaptWorkspace);window.addEventListener('workspace:before-navigate',beforeWorkspaceNavigation);hashNavigation();load();window.addEventListener('hashchange',hashNavigation);window.addEventListener('message',contextMessage);window.addEventListener('beforeunload',beforeUnload);if(embedded)window.parent.postMessage({type:'context.request'},location.origin)})
onBeforeUnmount(()=>{window.removeEventListener('resize',adaptWorkspace);window.removeEventListener('workspace:before-navigate',beforeWorkspaceNavigation);browserController?.abort();window.removeEventListener('hashchange',hashNavigation);window.removeEventListener('message',contextMessage);window.removeEventListener('beforeunload',beforeUnload);for(const notice of notifications)sonner.dismiss(notice)})

