ring(v.id)===String(key))))($event)"><div class="flex min-w-0 items-center gap-2"><TabsList variant="line" class="query-session-list h-9 max-w-full overflow-x-auto"><div v-for="session in sessions" :key="session.id" class="query-session inline-flex shrink-0 items-center gap-0.5"><TabsTrigger :disabled="busy" :value="String(session.id)" @keydown.delete.prevent="closeQuery(session.id)">{{session.name}}</TabsTrigger><Tooltip><TooltipTrigger as-child><span class="inline-flex" :tabindex="busy?0:undefined"><Button variant="ghost" size="icon-xs" type="button" :disabled="busy" :aria-label="'关闭'+session.name" @click.stop="closeQuery(session.id)"><XIcon class="size-3.5"/></Button></span></TooltipTrigger><TooltipContent>{{busy?'查询执行中，结束后可关闭':'关闭'+session.name}}</TooltipContent></Tooltip></div></TabsList><Button variant="ghost" size="icon" aria-label="新增标签" @click="newQuery()">+</Button></div><TabsContent v-for="session in sessions" :disabled="busy" :value="String(session.id)" force-mount v-show="!(String(activeSession.id)!==String(session.id))" class="min-w-0"></TabsContent></Tabs><div class="workspace-toolbar"><Tabs aria-label="工作区视图" :model-value="activeSession.advanced?'console':'browse'" @update:model-value="(value=>value==='console'?showConsole():showBrowser())($event)"><TabsList class="h-auto! flex-wrap gap-y-1 [&>[data-slot=tabs-trigger]]:h-7"><TabsTrigger :value="&quot;browse&quot;" :disabled="busy">{{kind==='dbms'?'数据浏览':'Key 浏览'}}</TabsTrigger><TabsTrigger :value="&quot;console&quot;" :disabled="busy">{{kind==='dbms'?'SQL 查询':'命令控制台'}}</TabsTrigger></TabsList></Tabs><span v-if="target" class="actual-target">实际目标：{{target.connection}} · {{kind==='dbms'?target.database:'DB '+target.db}}<span v-if="kind==='redis'&&target.key_prefix"> · Key 前缀 {{target.key_prefix}}</span></span><Button v-if="target" :aria-expanded="activeSession.navigationOpen" @click="activeSession.navigationOpen=!activeSession.navigationOpen" class="navigator-toggle" variant="outline" size="default" ty