st"><div class="section-head"><h3>可复用变更</h3><Button @click="open()" variant="default" size="default" type="button">＋ 新建变更</Button><Button v-if="form&&dirty" @click="operationList=false" variant="outline" size="default" type="button">继续编辑草稿</Button><InputGroup  class="min-w-0 "><InputGroupInput v-model="keyword" placeholder="筛选标题或应用"/><InputGroupAddon align="inline-end"><InputGroupButton v-if="keyword" :disabled="false" size="icon-xs" aria-label="清空输入" @click="keyword='' "><XIcon/></InputGroupButton></InputGroupAddon></InputGroup></div><div class="table-scroll"><div class="console-table min-w-0 max-w-full"><div class="max-w-full overflow-auto rounded-lg border" :style="{maxHeight:({x:676}).y?({x:676}).y+'px':undefined}"><Table class="table-fixed min-w-[var(--table-min-width)]" :style="{'--table-min-width':(({x:676}).x||({x:676}).minWidth||676)+'px'}"><TableHeader><TableRow><TableHead :style="{width:(180)+'px'}">变更</TableHead><TableHead :style="{width:(200)+'px'}">应用</TableHead><TableHead :style="{width:(120)+'px'}">状态</TableHead><TableHead :class="(pinTableActions?'right':undefined)==='right'?'sticky right-0 z-10 bg-background':(pinTableActions?'right':undefined)==='left'?'sticky left-0 z-10 bg-background':''" :style="{width:(176)+'px'}">操作</TableHead></TableRow></TableHeader><TableBody><template v-for="(record,rowIndex) in (((filtered)||[]).map((c,rowIndex)=>({...c,__rowKey:c.id}))||[])" :key="typeof (&quot;__rowKey&quot;)==='function'?(&quot;__rowKey&quot;)(record):record[&quot;__rowKey&quot;]??rowIndex"><TableRow><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record:c,rowIndex:rowIndex} in [{record,rowIndex}]"><div><b>{{c.title}}</b><small class="sub">#{{c.id}}</small></div></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record:c,rowIndex:rowIndex} in [{record,rowIndex}]"><div>{{c.service}}</div></template></div></